insert into public.translations (locale, key, value) values
  ('pt-BR', 'mods.tab.essentials', $json$"Essenciais"$json$::jsonb),
  ('en', 'mods.tab.essentials', $json$"Essentials"$json$::jsonb),
  ('es', 'mods.tab.essentials', $json$"Esenciales"$json$::jsonb),
  ('zh-CN', 'mods.tab.essentials', $json$"必需"$json$::jsonb),
  ('hi', 'mods.tab.essentials', $json$"ज़रूरी"$json$::jsonb),
